17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.io.IOException;
20	import java.util.Map;
21	import java.util.concurrent.ConcurrentHashMap;
22	
23	import org.springframework.core.Ordered;
24	import org.springframework.core.annotation.Order;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.MediaType;
27	import org.springframework.stereotype.Component;
28	import org.springframework.web.filter.OncePerRequestFilter;
29	import org.springframework.web.util.ContentCachingResponseWrapper;
30	
31	import jakarta.servlet.FilterChain;
32	import jakarta.servlet.ServletException;
33	import jakarta.servlet.http.HttpServletRequest;
34	import jakarta.servlet.http.HttpServletResponse;
35	
36	/**
37	 * Makes {@code POST /api/owners} idempotent per {@code Idempotency-Key} header. The first create
38	 * carrying a given key has its successful (201) response body remembered; a later create repeating
39	 * that key replays the originally created owner with 200 instead of creating a duplicate.
40	 */
41	@Component
42	@Order(Ordered.HIGHEST_PRECEDENCE)
43	public class OwnerIdempotencyFilter extends OncePerRequestFilter {
44	
45	    private final Map<String, byte[]> responses = new ConcurrentHashMap<>();
46	
47	    @Override
48	    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response,
49	                                    FilterChain filterChain) throws ServletException, IOException {
50	        String key = request.getHeader("Idempotency-Key");
51	        if (key == null || !isCreateOwner(request)) {
52	            filterChain.doFilter(request, response);
53	            return;
54	        }
55	        byte[] cached = responses.get(key);
56	        if (cached != null) {
57	            response.setStatus(HttpStatus.OK.value());
58	            response.setContentType(MediaType.APPLICATION_JSON_VALUE);
59	            response.getOutputStream().write(cached);
60	            return;
61	        }
62	        ContentCachingResponseWrapper wrapper = new ContentCachingResponseWrapper(response);
63	        filterChain.doFilter(request, wrapper);
64	        if (wrapper.getStatus() == HttpStatus.CREATED.value()) {
65	            responses.put(key, wrapper.getContentAsByteArray());
66	        }
67	        wrapper.copyBodyToResponse();
68	    }
69	
70	    private boolean isCreateOwner(HttpServletRequest request) {
71	        return "POST".equalsIgnoreCase(request.getMethod())
72	            && request.getRequestURI().endsWith("/api/owners");
73	    }
74	}
